local StudioService = game:GetService("StudioService")
local loggedInUserId = StudioService:GetUserId()

local developerInfo = Instance.new("ModuleScript")

local RunService = game:GetService("RunService")

-- 判断是否启动游戏
local isRunMode = RunService:IsRunMode()
local isRunning = RunService:IsRunning()

local isRun

if game["Run Service"]:IsServer() then
	isRun = isRunMode and isRunning
else
	isRun = not isRunMode and isRunning
end

if isRun and game["Run Service"]:IsServer() then
	developerInfo.Name = ".envUserInfo"
	developerInfo.Parent = game.ReplicatedStorage
	developerInfo.Source = [[
       return {
           UserId = ]] .. loggedInUserId .. [[
       }
   ]]
end

--[[
如果 game.ReplicatedStorage.env 存在，则读取该组件，获得一个对象。
该对象为一个数组，每一个成员的结构为:

* Name: 选项名称
* Type: 选项类型，包括：
   * boolean : 布尔值, 默认值为 false
   * number : 数字, 默认值为 0
   * string : 字符串, 默认值为 nil
   * single : 单选, 默认值为 nil
   * multiple : 多选, 默认值为 nil
* Options: 选项值，字符串数组, 如果 Type 为 single 或 multiple, 则需要提供一个选项值列表，


需要根据上述选项，生成一个 plugin 界面.
界面中包含生成提交按钮，点击按钮后，保存到 game.ReplicatedStorage.env.{loggedInUserId}
保存的值为上述选项的值，类型为对象，键值对为选项名称和选项值，使用 ModuleScript 保存。

打开界面时，读取 game.ReplicatedStorage.env.{loggedInUserId} 的值，并显示在界面上。
]]

-- 创建插件工具栏和按钮
local toolbar = plugin:CreateToolbar("DotEnv")
local toggleButton = toolbar:CreateButton("打开DotEnv", "打开DotEnv窗口", "rbxassetid://4458901886")

-- 创建插件窗口
local widgetInfo = DockWidgetPluginGuiInfo.new(Enum.InitialDockState.Float, false, false, 300, 400, 300, 400)

local widget = plugin:CreateDockWidgetPluginGui("DotEnvWidget", widgetInfo)
widget.Title = "DotEnv"

-- 创建界面元素
local frame = Instance.new("Frame")
frame.Size = UDim2.new(1, 0, 1, 0)
frame.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
frame.Parent = widget

local scrollFrame = Instance.new("ScrollingFrame")
scrollFrame.Size = UDim2.new(1, -20, 1, -70)
scrollFrame.Position = UDim2.new(0, 10, 0, 10)
scrollFrame.BackgroundTransparency = 1
scrollFrame.Parent = frame

local uiListLayout = Instance.new("UIListLayout")
uiListLayout.Padding = UDim.new(0, 5)
uiListLayout.Parent = scrollFrame

local zIndex = 100

local function loadEnvOptions()
	local envOptions = game.ReplicatedStorage:FindFirstChild(".env")
	if not envOptions then
		return {}
	end

	-- 加载已保存的值
	local savedValues = {}
	local envPlayers = game.ReplicatedStorage:FindFirstChild(".envPlayers")
	if envPlayers then
		local userValues = envPlayers:FindFirstChild(tostring(loggedInUserId))
		if userValues then
			local success, result = pcall(require, userValues:Clone())
			if success then
				savedValues = result
			end
		end
	end

	-- 返回选项定义和已保存的值
	return require(envOptions:Clone()), savedValues
end

-- 创建自定义复选框
local function createCheckBox()
	local button = Instance.new("TextButton")
	button.Size = UDim2.new(0, 20, 0, 20)
	button.Text = ""
	button.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
	button.BorderColor3 = Color3.fromRGB(0, 0, 0)

	local checked = false
	button.MouseButton1Click:Connect(function()
		checked = not checked
		button.BackgroundColor3 = checked and Color3.fromRGB(0, 170, 255) or Color3.fromRGB(255, 255, 255)
	end)

	return button
end

-- 创建自定义下拉框
local function createDropDown(options, multiple)
	local container = Instance.new("Frame")
	container.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
	container.ZIndex = zIndex

	local useOriginValue = true

	local button = Instance.new("TextButton")
	button.Size = UDim2.new(1, 0, 1, 0)
	button.Text = "选择..."
	button.TextXAlignment = Enum.TextXAlignment.Left
	button.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
	button.BorderColor3 = Color3.fromRGB(0, 0, 0)
	button.Parent = container
	button.ZIndex = zIndex

	local dropDownFrame = Instance.new("Frame")
	dropDownFrame.Size = UDim2.new(1, 0, 0, #options * 25)
	dropDownFrame.Position = UDim2.new(0, 0, 1, 0)
	dropDownFrame.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
	dropDownFrame.BorderColor3 = Color3.fromRGB(0, 0, 0)
	dropDownFrame.Visible = false
	dropDownFrame.Parent = container
	button.ZIndex = zIndex

	local selectedValues = {}

	for i, option in ipairs(options) do
		local optionButton = Instance.new("TextButton")
		optionButton.Size = UDim2.new(1, 0, 0, 25)
		optionButton.Position = UDim2.new(0, 0, 0, (i - 1) * 25)
		optionButton.Text = option
		optionButton.TextXAlignment = Enum.TextXAlignment.Left
		optionButton.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
		optionButton.Parent = dropDownFrame
		optionButton.ZIndex = zIndex

		-- 添加选项按钮的右键点击事件
		optionButton.MouseButton2Click:Connect(function()
			dropDownFrame.Visible = false
		end)

		if multiple then
			local checkbox = createCheckBox()
			checkbox.Size = UDim2.new(0, 15, 0, 15)
			checkbox.Position = UDim2.new(1, -20, 0.5, -7.5)
			checkbox.Parent = optionButton
			checkbox.ZIndex = zIndex

			-- 添加复选框的右键点击事件
			checkbox.MouseButton2Click:Connect(function()
				dropDownFrame.Visible = false
			end)

			optionButton.MouseButton1Click:Connect(function()
				local isSelected = not selectedValues[option]
				selectedValues[option] = isSelected
				checkbox.BackgroundColor3 = isSelected and Color3.fromRGB(0, 170, 255) or Color3.fromRGB(255, 255, 255)

				local selectedText = ""
				for value, selected in pairs(selectedValues) do
					if selected then
						selectedText = selectedText .. value .. ", "
					end
				end
				button.Text = selectedText:sub(1, -3) or "选择..."
			end)
		else
			optionButton.MouseButton1Click:Connect(function()
				button.Text = option
				dropDownFrame.Visible = false
				selectedValues = { [option] = true }
			end)
		end
	end

	button.MouseButton1Click:Connect(function()
		dropDownFrame.Visible = not dropDownFrame.Visible
		if dropDownFrame.Visible then
			button.Text = "选择..."
		end
		useOriginValue = false
	end)

	-- 添加鼠标右键点击事件处理
	button.MouseButton2Click:Connect(function()
		dropDownFrame.Visible = false
	end)

	-- 为整个游戏视图添加鼠标右键点击事件
	game:GetService("UserInputService").InputBegan:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton2 then
			dropDownFrame.Visible = false
		end
	end)

	return container,
		function()
			if multiple then
				local result = {}
				for value, selected in pairs(selectedValues) do
					if selected then
						table.insert(result, value)
					end
				end
				return result
			else
				for value, selected in pairs(selectedValues) do
					if selected then
						return value
					end
				end
				return nil
			end
		end,
		function()
			return useOriginValue
		end
end

-- 修改createOptionControl函数，添加初始值支持
local function createOptionControl(option, savedValues)
	local container = Instance.new("Frame")
	container.Size = UDim2.new(1, 0, 0, 30)
	container.BackgroundTransparency = 1
	container.ZIndex = zIndex
	zIndex = zIndex - 1

	local label = Instance.new("TextLabel")
	label.Size = UDim2.new(0.4, -20, 1, 0)
	label.Position = UDim2.new(0, 10, 0, 0)
	label.Text = option.Name
	label.TextXAlignment = Enum.TextXAlignment.Left
	label.BackgroundTransparency = 1
	label.Parent = container

	local control
	local getValue
	local savedValue = savedValues[option.Name]

	if option.Type == "boolean" then
		control = createCheckBox()
		control.Position = UDim2.new(0.5, 0, 0, 5)
		-- ���置初始值
		if savedValue ~= nil then
			control.BackgroundColor3 = savedValue and Color3.fromRGB(0, 170, 255) or Color3.fromRGB(255, 255, 255)
		end
		getValue = function()
			local value = control.BackgroundColor3 == Color3.fromRGB(0, 170, 255)
			return value, value == (option.Default or false)
		end
	elseif option.Type == "number" then
		control = Instance.new("TextBox")
		control.Size = UDim2.new(0.5, -20, 1, 0)
		control.Position = UDim2.new(0.5, 0, 0, 0)
		-- 设置初始值
		control.Text = tostring(savedValue or option.Default or 0)
		getValue = function()
			local value = tonumber(control.Text) or 0
			return value, value == (option.Default or 0)
		end
	elseif option.Type == "string" then
		control = Instance.new("TextBox")
		control.Size = UDim2.new(0.5, -20, 1, 0)
		control.Position = UDim2.new(0.5, 0, 0, 0)
		-- 设置初始值
		control.Text = savedValue or option.Default or ""
		getValue = function()
			local value = control.Text
			return value, value == (option.Default or "")
		end
	elseif option.Type == "single" or option.Type == "multiple" then
		local useOriginValueHandler
		control, getValue, useOriginValueHandler = createDropDown(option.Options or {}, option.Type == "multiple")
		control.Size = UDim2.new(0.5, -20, 0, 30)
		control.Position = UDim2.new(0.5, 0, 0, 0)
		-- 设置初始值
		if savedValue then
			local button = control:FindFirstChild("TextButton")
			if button then
				if option.Type == "multiple" then
					local text = table.concat(savedValue, ", ")
					button.Text = text ~= "" and text or "选择..."
				else
					button.Text = savedValue or "选择..."
				end
			end
		end
		local originalGetValue = getValue
		local refSavedValue = savedValue
		getValue = function()
			local value = originalGetValue()
			if useOriginValueHandler() then
				value = refSavedValue
			end
			print("...Value", value)
			if option.Type == "multiple" then
				return value, #(value or {}) == 0
			else
				return value, value == nil
			end
		end
	end

	if control then
		control.Parent = container
	end

	return container, getValue
end

