-- 添加table转换为Lua字符串的函数
local function valueToString(value)
	if type(value) == "string" then
		return string.format("%q", value) -- 处理字符串，添加引号并转义
	elseif type(value) == "table" then
		local parts = {}
		-- 检查是否为数组
		local isArray = true
		local maxIndex = 0
		for k, _ in pairs(value) do
			if type(k) ~= "number" or k <= 0 or math.floor(k) ~= k then
				isArray = false
				break
			end
			maxIndex = math.max(maxIndex, k)
		end

		if isArray then
			-- 数组格式
			for i = 1, maxIndex do
				table.insert(parts, valueToString(value[i]))
			end
		else
			-- 对象格式
			for k, v in pairs(value) do
				if type(k) == "string" then
					table.insert(parts, string.format("[%q]=%s", k, valueToString(v)))
				else
					table.insert(parts, string.format("[%s]=%s", tostring(k), valueToString(v)))
				end
			end
		end
		return "{" .. table.concat(parts, ",") .. "}"
	else
		return tostring(value) -- 处理数字、布尔值等
	end
end

-- 修改保存函数
local function saveUserValues(values)
	-- 确保 __developer 文件夹存在
	local envOptions = game.ReplicatedStorage:FindFirstChild(".env")
	if not envOptions then
		return
	end

	-- 确保用户文件夹存在
	local envPlayers = game.ReplicatedStorage:FindFirstChild(".envPlayers")
	if not envPlayers then
		envPlayers = Instance.new("Folder")
		envPlayers.Name = ".envPlayers"
		envPlayers.Parent = game.ReplicatedStorage
	end
	local userValue = envPlayers:FindFirstChild(tostring(loggedInUserId))
	if not userValue then
		userValue = Instance.new("ModuleScript")
		userValue.Name = tostring(loggedInUserId)
		userValue.Parent = envPlayers
	end

	-- 转换为Lua格式的字符串
	local source = "return " .. valueToString(values)
	userValue.Source = source
end

-- 修改updateUI函数
local valueGetters = {}

local function updateUI()
	-- 清除现有控件和getter函数
	valueGetters = {}
	for _, child in ipairs(scrollFrame:GetChildren()) do
		if child:IsA("Frame") then
			child:Destroy()
		end
	end

	-- 创建新控件
	local options, savedValues = loadEnvOptions()
	for _, option in ipairs(options) do
		local control, getValue = createOptionControl(option, savedValues)
		control.Parent = scrollFrame
		valueGetters[option.Name] = getValue
	end
end

-- 添加保存按钮点击事件
saveButton.MouseButton1Click:Connect(function()
	local values = {}
	for name, getter in pairs(valueGetters) do
		local value, isDefault = getter()
		if not isDefault then
			values[name] = value
		end
	end
	saveUserValues(values)
end)

-- 切换窗口显示状态
toggleButton.Click:Connect(function()
	widget.Enabled = not widget.Enabled
	if widget.Enabled then
		updateUI()
	end
end)

-- 初始化
updateUI()
